// Config sources: the list of lender pages to crawl.
// Why: one place to add or change sites. Each item becomes one HTTP request.
// To use a real site, change the url (static HTML pages only).
const sources = [
  { provider: 'QuickCredit Bank', url: 'http://host.docker.internal:8080/bank_a.html' },
  { provider: 'FinEasy Lenders',  url: 'http://host.docker.internal:8080/bank_b.html' },
];
return sources.map(s => ({ json: s }));

// Normalize: turns the extracted text arrays into ONE SQL upsert statement.
// Why: one DB call is faster, and the SQL keeps old values if a field cannot be parsed.
const cfg = $('Config sources').all();   // same order as the HTTP results
const pages = $input.all();              // one item per site (arrays: names, rates, rules)

// Small helpers. They make values safe to put inside SQL text.
const asArr = v => Array.isArray(v) ? v : (v ? [v] : []);
const q = s => (s === null || s === undefined || s === '') ? 'NULL' : "'" + String(s).replace(/'/g, "''") + "'";
const n = v => (v === null || v === undefined || isNaN(v)) ? 'NULL' : String(Number(v));
const toNum = t => Number(String(t).replace(/,/g, ''));
const arr = a => a.length ? 'ARRAY[' + a.map(q).join(',') + ']::text[]' : 'NULL::text[]';

// Reads the rule text and pulls out numbers we can store in columns.
// Anything we cannot read stays null (the LLM stage reads the raw text later).
function parseRule(text) {
  const r = text || '';
  const inc = r.match(/income[^0-9]{0,30}([0-9][0-9,]*)/i);
  const sc2 = r.match(/score[^0-9]{0,15}([0-9]{3})\s*(?:to|-|and)\s*([0-9]{3})/i);
  const sc1 = r.match(/score[^0-9]{0,15}([0-9]{3})/i);
  const ag2 = r.match(/\bage\b[^0-9]{0,15}([0-9]{2})\s*(?:to|-|and)\s*([0-9]{2})/i);
  const ag1 = r.match(/\bage\b[^0-9]{0,15}([0-9]{2})/i);
  const low = r.toLowerCase();
  const emp = [];
  if (low.includes('salaried')) emp.push('salaried');
  if (/self[- ]employed/.test(low)) emp.push('self-employed');
  if (low.includes('business')) emp.push('business');
  return {
    minIncome: inc ? toNum(inc[1]) : null,
    minScore: sc2 ? Number(sc2[1]) : (sc1 ? Number(sc1[1]) : null),
    maxScore: sc2 ? Number(sc2[2]) : null,
    minAge: ag2 ? Number(ag2[1]) : (ag1 ? Number(ag1[1]) : null),
    maxAge: ag2 ? Number(ag2[2]) : null,
    employment: emp,
  };
}

const rows = new Map();   // key = provider|name, so one statement never repeats a row
const counts = {};
pages.forEach((page, i) => {
  const provider = cfg[i].json.provider;
  const url = cfg[i].json.url;
  const names = asArr(page.json.names);
  const rates = asArr(page.json.rates);
  const rules = asArr(page.json.rules);
  counts[provider] = 0;
  names.forEach((name, j) => {
    const nm = String(name).trim();
    if (!nm) return;
    const text = String(rules[j] || '').replace(/\s+/g, ' ').trim();
    const rate = String(rates[j] || '').match(/([0-9]+(?:\.[0-9]+)?)\s*%/);
    rows.set(provider + '|' + nm, { provider, nm, url, text, rate: rate ? Number(rate[1]) : null, ...parseRule(text) });
    counts[provider] += 1;
  });
});

const emptySites = Object.keys(counts).filter(k => counts[k] === 0);
const values = [...rows.values()].map(r =>
  `(${q(r.provider)},${q(r.nm)},${q(r.url)},${n(r.rate)},${n(r.minIncome)},${n(r.minScore)},${n(r.maxScore)},${n(r.minAge)},${n(r.maxAge)},${arr(r.employment)},${q(r.text)},${r.text ? 'md5(' + q(r.text) + ')' : 'NULL'},now())`
);

// With no rows we send a harmless query that returns nothing.
const sql = values.length === 0 ? 'SELECT 1 AS product_id WHERE false' :
`INSERT INTO loan_products (provider, product_name, source_url, interest_rate, min_monthly_income, min_credit_score, max_credit_score, min_age, max_age, allowed_employment, eligibility_text, raw_hash, last_seen_at)
VALUES
${values.join(',\n')}
ON CONFLICT (provider, product_name) DO UPDATE SET
  source_url = EXCLUDED.source_url,
  interest_rate = COALESCE(EXCLUDED.interest_rate, loan_products.interest_rate),
  min_monthly_income = COALESCE(EXCLUDED.min_monthly_income, loan_products.min_monthly_income),
  min_credit_score = COALESCE(EXCLUDED.min_credit_score, loan_products.min_credit_score),
  max_credit_score = COALESCE(EXCLUDED.max_credit_score, loan_products.max_credit_score),
  min_age = COALESCE(EXCLUDED.min_age, loan_products.min_age),
  max_age = COALESCE(EXCLUDED.max_age, loan_products.max_age),
  allowed_employment = COALESCE(EXCLUDED.allowed_employment, loan_products.allowed_employment),
  eligibility_text = COALESCE(EXCLUDED.eligibility_text, loan_products.eligibility_text),
  raw_hash = COALESCE(EXCLUDED.raw_hash, loan_products.raw_hash),
  last_seen_at = now()
RETURNING product_id, provider, product_name`;

return [{ json: { sql, total: rows.size, per_site: counts, empty_sites: emptySites } }];

// Summary: counts the rows the database confirmed. Good to show in the demo.
const done = $input.all().filter(i => i.json.product_id);
return [{ json: { products_upserted: done.length, products: done.map(i => i.json.provider + ' - ' + i.json.product_name) } }];

// Log empty sites: writes a clear warning for every site that gave 0 products.
// Why: the workflow must not fail, but the developer should still see the problem.
const sites = $json.empty_sites;
sites.forEach(s => console.log('WARNING: 0 products from site ' + s));
return [{ json: { warning: sites.map(s => '0 products from site ' + s), sites } }];
